INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c5e3932d-a9cc-48fe-8b4f-98c21c47e194','en_MZ','ATTENDANCE_REGISTER_README_ERROR_1','Register ID is required when boundary is selected — A boundary column has been filled but the Register ID cell is empty. The Register ID is auto-populated by formula — ensure you have not accidentally cleared it.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1a0e36c7-f012-4bf0-897e-05902b03d615','en_MZ','ATTENDANCE_REGISTER_README_ERROR_2','At least one boundary must be selected for the register — A Register ID has been entered but no boundary column has a value. Fill at least one boundary column for every register row.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('72de463e-154d-4a81-908a-80fc01ae079b','en_MZ','ATTENDANCE_REGISTER_README_ERROR_3','Invalid boundary code — The boundary value entered is not recognised for this campaign. Use only the boundary codes available in the column dropdowns.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5c586b08-a70d-4489-bed6-35a42a815d95','en_MZ','ATTENDANCE_REGISTER_README_ERROR_4','Duplicate Register ID found — The same Register ID appears more than once within the sheet. Each register must have a unique ID. If you created multiple registers at the same boundary, overwrite the auto-populated Register ID to make each one unique.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7909008c-28c7-4e72-b12d-cd255f6a47ea','en_MZ','ATTENDANCE_REGISTER_README_ERROR_5','Register ID already exists in the system — This Register ID has already been created in a previous upload. Remove or rename the duplicate row before re-uploading.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b38f1489-644a-4d53-ad35-4f508d3e15fb','en_MZ','ATTENDANCE_REGISTER_README_ERROR_HEADER','Common errors and what they mean:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1421b69f-7cf7-4ad5-aa7d-529f4fc49896','en_MZ','ATTENDANCE_REGISTER_README_HEADER_1','How to fill this template:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a371593c-2f93-49b5-80ac-6c9768b4c2c9','en_MZ','ATTENDANCE_REGISTER_README_IMPORTANT','Important','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('095a8a35-1616-4bc1-a1e1-17f41e85d968','en_MZ','ATTENDANCE_REGISTER_README_IMPORTANT_DESC','Once registers are successfully created, their boundary and project details cannot be changed from this screen. Contact your system administrator for any corrections.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ef8f5e57-4ba8-4947-988a-bd9951cc6054','en_MZ','ATTENDANCE_REGISTER_README_STEP_1','Download the template using the button above and open it in Microsoft Excel or a compatible spreadsheet application. Do not convert the file to CSV before uploading, as the auto-fill formulas in the Register ID column may stop working.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d86f5959-6735-4b17-90c5-86a58b9ef6d7','en_MZ','ATTENDANCE_REGISTER_README_STEP_2','Each row in the template represents one attendance register. Fill in the boundary columns from left to right — for example, State, then District, then the lowest level you want the register created at. You must fill at least one boundary column per row; rows with no boundary filled will be rejected. The register will be created at the lowest boundary level you have filled in.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e96bf111-6546-480f-b299-affa7ca59116','en_MZ','ATTENDANCE_REGISTER_README_STEP_3','The Register ID column is auto-populated based on the lowest boundary you enter. You may overwrite this value if you want a custom name, but every Register ID in the sheet must be unique — duplicate IDs will cause an error and the entire upload will be rejected until resolved.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4f909520-4f62-41f1-b310-683436f26a89','en_MZ','ATTENDANCE_REGISTER_README_STEP_4','What happens after you upload: Your file will be processed in the background. You will see a status update on this screen once processing is complete. If any rows have errors, you will be able to download a copy of your file with error details noted against each row. Fix the flagged rows and re-upload to complete register creation.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c0eff4da-b781-46d5-9f40-4435aeb21e36','en_MZ','ATTENDEE_README_ENROLLMENT_DESC_1','When a user is mapped to a register, their enrollment date is set automatically to the date of mapping — you do not need to fill this column. The enrollment date determines from which day attendance can be marked for that user.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('46e98153-f499-4d3f-95fb-3c3afcc45931','en_MZ','ATTENDEE_README_ENROLLMENT_DESC_2','If you need to remove a user from a register, set their Status column to Disabled. This will trigger an immediate de-enrollment, and attendance cannot be marked for that user from that date onwards. If you enter a future date in the De-enrollment Date column instead, the user will remain active until that date and attendance marking will be automatically blocked after it.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6e57597f-79f0-43d6-81ef-f0f7d60a07ca','en_MZ','ATTENDEE_README_ENROLLMENT_DESC_3','If you need to move a user from one register to another, you must first disable them from their current register. Once their status is set to Disabled and the file is uploaded, they can be mapped to a new register, this can be done on the same day.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2ef9d861-66ea-41f8-8097-469f52e2de7c','en_MZ','ATTENDEE_README_ERROR_1','Register ID is required — A pre-filled Register ID was accidentally cleared. Re-download the template and do not edit any pre-filled cells.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dc79fae6-4b11-40ac-a2d4-b2d280f4079a','en_MZ','ATTENDEE_README_ERROR_10','Cannot change de-enrollment date for this register — The de-enrollment date is locked once set. Contact your system administrator if this needs to be changed.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c519c9f1-3ca0-46c6-80f8-9a230f8d198e','en_MZ','ATTENDEE_README_ERROR_2','Register ID does not match expected register — A row contains a Register ID from a different template. Re-download the template for this register and re-enter the data.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('677845b5-5655-4ef3-8c65-f1ed58a5bfdd','en_MZ','ATTENDEE_README_ERROR_3','Register already exists in a different campaign — The register belongs to another campaign and the entire sheet will be rejected. Ensure you have downloaded the template from the correct campaign.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('89f0b82f-a0b6-429c-8958-58ed3c18dca7','en_MZ','ATTENDEE_README_ERROR_4','Enrollment date is required to enroll a new attendee or staff — Enrollment Date is mandatory for all new users, and must also be filled if Team Code or De-enrollment Date is entered. Use DD-MM-YYYY or DD/MM/YYYY format.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8388d782-8b63-4003-928e-12ae7c13ddc6','en_MZ','ATTENDEE_README_ERROR_5','Invalid date format. Use DD-MM-YYYY or DD/MM/YYYY — A date cell contains an unrecognised format or extra characters. Accepted formats are DD-MM-YYYY and DD/MM/YYYY only.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f5a4fb39-86f4-4421-93ec-b1a43757e79c','en_MZ','ATTENDEE_README_ERROR_6','Date must be between register start and end dates — An Enrollment or De-enrollment Date falls outside the register''s valid date range. Check the campaign dates and correct accordingly.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4d34b5b6-691e-4a8a-bb70-fe59bf4bdd2f','en_MZ','ATTENDEE_README_ERROR_7','De-enrollment date cannot be before enrollment date — The De-enrollment Date is earlier than the Enrollment Date on the same row. Correct so that de-enrollment is on or after enrollment.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a142f1c9-cc2f-466c-8227-a53cf88b1bcb','en_MZ','ATTENDEE_README_ERROR_8','Individual is already actively enrolled in another attendance register — This user must be de-enrolled from their current register before being added here. Once de-enrolled, they can be mapped to this register on the same day.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('59df45c6-d90a-4537-8f0a-0a7f063b1b35','en_MZ','ATTENDEE_README_ERROR_9','Cannot change enrollment date for this register — The enrollment date from a user''s previous enrollment in this register cannot be modified. Leave it as it was in the original record.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d9c10013-b12a-40cb-a93e-052ff567beef','en_MZ','ATTENDEE_README_HEADER_1','How to fill this template:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d23410b6-d6c8-4bf7-9bef-b26b45d7758d','en_MZ','ATTENDEE_README_HEADER_2','Common errors and what they mean:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('1e31a625-6c87-4707-8582-0af513256cff','en_MZ','ATTENDEE_README_HEADER_3','Common errors and what they mean:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ad6c7213-0f1d-49d7-87f1-7babd66168a7','en_MZ','ATTENDEE_README_STEP_1','Download the template using the button above. The template will be pre-filled with all users currently created in the system, split across three sheets — Frontline Workers, Attendance Markers, and Attendance Approvers. Always download a fresh copy of the template before filling it, as the user list and available registers may have changed since your last download.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ef7b5e02-9653-4112-9fc1-387046622b75','en_MZ','ATTENDEE_README_STEP_2','Columns highlighted in grey (User ID, Name, Login ID, Role, Boundary, and Register ID) are locked and must not be edited. Any changes to these columns will cause that row to be rejected on upload.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06d8df3b-e04a-4ff5-afb0-d369a32eeb57','en_MZ','ATTENDEE_README_STEP_3','This template is specific to a single register — the Register ID is already pre-filled for all rows and cannot be changed. If you need to map users to a different register, download the template from that register separately.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('62040327-4e3c-4e0a-9bdb-25203e4840f4','en_MZ','ATTENDEE_README_STEP_4','`Enrollment Date` is mandatory for all users. It decides from when attendance can be marked in the register. Rows without this date will be skipped and users will not be mapped. Enter the date in DD-MM-YYYY format. The date should be within the campaign duration','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('89df8e34-0d79-4f90-a222-e073f8d73ded','en_MZ','ATTENDEE_README_STEP_5','De-enrollment date: The De-enrollment Date column is optional. If you enter a future date here, the user will remain active until that date and attendance marking will be automatically blocked from the following day onwards.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b0878c93-3c2b-443d-b455-aaf04503e32b','en_MZ','ATTENDEE_README_STEP_6','If you need to move a user from one register to another, they must be de-enrolled from their current register first. Once de-enrolled, they can be mapped to a new register on any day after their de-enrollment date.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a76bde17-bbc8-4c3b-8c4e-6a8e2f81653f','en_MZ','ATTENDEE_README_STEP_7','What happens after you upload: Your file will be processed in the background. You will see a status update on this screen once processing is complete.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
