INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d4b1ee4d-b656-424c-a8e0-7df31d81030f','en_MZ','MODULE_DESCRIPTION_INSIDEMONITORING','Captures post-campaign household-level data to validate vaccination coverage, similar to LQAS. Monitors record GPS points, survey responses, missed vaccination reasons, caregiver awareness, and surveillance details. Provides a settlement summary (missed children count, risk flags, coverage status, comments) and is accessible only to configured monitor roles.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a7648c1e-3b51-40cf-be1a-9b44e7b58a34','en_MZ','MODULE_DESCRIPTION_LQA','The Lot/Cluster Header in an LQA survey records location details, surveyor information, and GPS coordinates. It includes state, district, village, cluster ID, enumerator name, supervisor details, latitude, longitude, and survey date. This ensures accurate tracking, verification, and reporting of field survey activities.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('044ee779-cb4f-4133-b6ab-ea3c5088984f','en_MZ','MODULE_DESCRIPTION_STOCK','Track and update resources stock levels at each distribution point. Record receipts, issues, consumption, and losses to maintain accurate visibility of medicines across the campaign.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4c939fa8-728c-48a0-bfd6-f906398aacb0','en_MZ','MODULE_FEATURES','Module Features','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
