INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3ae446f9-488d-4f75-b438-521cf4bb2d0c','pt_MZ','APP_CONFIG_PAGE_VIALDETAILSMENU','Detalhes do frasco','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6d68b0cb-a0cb-43dc-8f48-59329a296983','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_1','O ID do registro é necessário quando o limite é selecionado — Uma coluna de limite foi preenchida, mas a célula ID do registro está vazia. O ID do registro é preenchido automaticamente por fórmula – certifique-se de não apagá-lo acidentalmente.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('eac15ae5-9dd2-4297-ae56-74f5e8886f0d','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_2','Pelo menos um limite deve ser selecionado para o registro — Um ID de registro foi inserido, mas nenhuma coluna de limite possui um valor. Preencha pelo menos uma coluna de limite para cada linha de registro.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7574525e-f384-41ca-93d3-57ae168abfdd','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_3','Código de limite inválido — O valor de limite inserido não é reconhecido para esta campanha. Use apenas os códigos de limite disponíveis nos menus suspensos da coluna.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a1adadf7-36b7-4edb-ade3-4751a42d19a1','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_4','ID de registro duplicado encontrado — O mesmo ID de registro aparece mais de uma vez na planilha. Cada registro deve ter um ID único. Se você criou vários registros no mesmo limite, substitua o ID do registro preenchido automaticamente para tornar cada um deles exclusivo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('06659e73-c762-46fa-b52c-5268ffa4de2d','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_5','Register ID já existe no sistema — Este Register ID já foi criado em um upload anterior. Remova ou renomeie a linha duplicada antes de fazer upload novamente.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('824794cc-21b1-41f2-9768-4e0537f95036','pt_MZ','ATTENDANCE_REGISTER_README_ERROR_HEADER','Erros comuns e o que eles significam:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('142c044f-d21f-493d-ab59-27d25246dba1','pt_MZ','ATTENDANCE_REGISTER_README_HEADER_1','Como preencher este modelo:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('65c933d1-cd55-4f83-bc76-5b9f1123627d','pt_MZ','ATTENDANCE_REGISTER_README_IMPORTANT','Importante','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f9160491-7e1d-4661-9ded-750b16f089d9','pt_MZ','ATTENDANCE_REGISTER_README_IMPORTANT_DESC','Depois que os registros forem criados com sucesso, seus limites e detalhes do projeto não poderão ser alterados nesta tela. Entre em contato com o administrador do sistema para quaisquer correções.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dd15d8a4-523c-48b9-a3a3-08842d20c22f','pt_MZ','ATTENDANCE_REGISTER_README_STEP_1','Baixe o modelo usando o botão acima e abra-o no Microsoft Excel ou em um aplicativo de planilha compatível. Não converta o arquivo para CSV antes de carregá-lo, pois as fórmulas de preenchimento automático na coluna ID do registro podem parar de funcionar.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8b590495-0fc1-46c0-9211-8b91e6ee5b43','pt_MZ','ATTENDANCE_REGISTER_README_STEP_2','Cada linha do modelo representa um registro de presença. Preencha as colunas de limite da esquerda para a direita — por exemplo, Estado, depois Distrito e, em seguida, o nível mais baixo em que deseja que o registro seja criado. Você deve preencher pelo menos uma coluna de limite por linha; linhas sem limite preenchido serão rejeitadas. O registro será criado no nível de limite mais baixo que você preencheu.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c44eae56-5dde-47c7-ba05-1fa4d5c2ec71','pt_MZ','ATTENDANCE_REGISTER_README_STEP_3','A coluna Register ID é preenchida automaticamente com base no limite mais baixo inserido. Você pode substituir esse valor se quiser um nome personalizado, mas cada ID de registro na planilha deve ser exclusivo — IDs duplicados causarão um erro e todo o upload será rejeitado até ser resolvido.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4978aa04-6632-4a5e-bfa5-2b5d20200bb4','pt_MZ','ATTENDANCE_REGISTER_README_STEP_4','O que acontece depois do upload: seu arquivo será processado em segundo plano. Você verá uma atualização de status nesta tela assim que o processamento for concluído. Se alguma linha apresentar erros, você poderá fazer download de uma cópia do seu arquivo com os detalhes dos erros anotados em cada linha. Corrija as linhas sinalizadas e faça upload novamente para concluir a criação do registro.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('237159b9-41a5-43ee-9875-834457d2beb7','pt_MZ','ATTENDEE_README_ENROLLMENT_DESC_1','Quando um usuário é mapeado para um cadastro, sua data de inscrição é definida automaticamente para a data do mapeamento — não é necessário preencher esta coluna. A data de inscrição determina a partir de qual dia a frequência poderá ser marcada para aquele usuário.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4aa13497-3fd9-4045-a546-12fd2bfc57c6','pt_MZ','ATTENDEE_README_ENROLLMENT_DESC_2','Se você precisar remover um usuário de um cadastro, defina sua coluna Status como Desativado. Isso acionará o cancelamento imediato da inscrição e a presença não poderá ser marcada para esse usuário a partir dessa data. Se você inserir uma data futura na coluna Data de Desinscrição, o usuário permanecerá ativo até essa data e a marcação de frequência será automaticamente bloqueada após ela.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d8f8ad79-e25d-464b-8a4a-d3771f75b92e','pt_MZ','ATTENDEE_README_ENROLLMENT_DESC_3','Se você precisar mover um usuário de um registro para outro, você deve primeiro desativá-lo do seu registro atual. Uma vez que seu status esteja definido como Desativado e o upload do arquivo, eles poderão ser mapeados para um novo cadastro, isso pode ser feito no mesmo dia.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ce6b91f0-bbc5-49ff-84b5-1d379ed44d29','pt_MZ','ATTENDEE_README_ERROR_1','O ID de registro é obrigatório — Um ID de registro pré-preenchido foi apagado acidentalmente. Baixe novamente o modelo e não edite nenhuma célula pré-preenchida.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4c2b2578-7595-4022-8a94-fea07e0db207','pt_MZ','ATTENDEE_README_ERROR_10','Não é possível alterar a data de cancelamento da inscrição para este registro — A data de cancelamento da inscrição é bloqueada depois de definida. Entre em contato com o administrador do sistema se isso precisar ser alterado.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0b0a3a17-aa9e-48a4-9263-da75463b2d85','pt_MZ','ATTENDEE_README_ERROR_2','O ID do registro não corresponde ao registro esperado — Uma linha contém um ID do registro de um modelo diferente. Baixe novamente o modelo para este registro e insira novamente os dados.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('48698626-fc22-43ed-8b38-908a29b45cf7','pt_MZ','ATTENDEE_README_ERROR_3','Cadastro já existe em outra campanha — O cadastro pertence a outra campanha e toda a planilha será rejeitada. Certifique-se de ter baixado o modelo da campanha correta.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e08c2792-f2aa-4e5f-a78e-ebd49ce5937b','pt_MZ','ATTENDEE_README_ERROR_4','A data de inscrição é obrigatória para inscrever um novo participante ou equipe — a data de inscrição é obrigatória para todos os novos usuários e também deve ser preenchida se o código da equipe ou a data de cancelamento de inscrição forem inseridos. Use o formato DD-MM-AAAA ou DD/MM/AAAA.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8233718b-affb-49dc-bd15-a7b920671f0a','pt_MZ','ATTENDEE_README_ERROR_5','Formato de data inválido. Use DD-MM-AAAA ou DD/MM/AAAA — Uma célula de data contém um formato não reconhecido ou caracteres extras. Os formatos aceitos são apenas DD-MM-AAAA e DD/MM/AAAA.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('f930b0bc-aa70-4b9a-941e-9c1cc28a18ca','pt_MZ','ATTENDEE_README_ERROR_6','A data deve estar entre as datas de início e término do registro — uma data de inscrição ou cancelamento de inscrição está fora do intervalo de datas válido do registro. Verifique as datas da campanha e corrija de acordo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8640e270-153e-4d0f-a0bc-a4962c789861','pt_MZ','ATTENDEE_README_ERROR_7','A data de cancelamento de inscrição não pode ser anterior à data de inscrição — A data de cancelamento de inscrição é anterior à data de inscrição na mesma linha. Corrija para que o cancelamento da inscrição ocorra no momento ou após a inscrição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3599e1b1-7704-4dce-ba89-0d32aba60fac','pt_MZ','ATTENDEE_README_ERROR_8','Indivíduo já está ativamente inscrito em outro cadastro de presença — Este usuário deve ter sua inscrição cancelada em seu cadastro atual antes de ser adicionado aqui. Uma vez cancelados, eles podem ser mapeados para este cadastro no mesmo dia.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20bbbf3d-5860-400c-8b52-f5c89006468e','pt_MZ','ATTENDEE_README_ERROR_9','Não é possível alterar a data de inscrição neste cadastro — A data de inscrição da inscrição anterior de um usuário neste cadastro não pode ser modificada. Deixe como estava no registro original.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('813db699-7d0d-4547-b726-b7b068d321b9','pt_MZ','ATTENDEE_README_HEADER_1','Como preencher este modelo:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9b4f7e40-e1ec-451f-a917-c226e1ae413f','pt_MZ','ATTENDEE_README_HEADER_2','Erros comuns e o que eles significam:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('87ed39d4-7b72-43e3-b42f-1197317b5c8c','pt_MZ','ATTENDEE_README_HEADER_3','Erros comuns e o que eles significam:','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cf57be83-5359-4964-a718-1eff2d58e195','pt_MZ','ATTENDEE_README_STEP_1','Baixe o modelo usando o botão acima. O modelo será pré-preenchido com todos os usuários atualmente criados no sistema, divididos em três planilhas – Trabalhadores da Linha de Frente, Marcadores de Presença e Aprovadores de Presença. Sempre baixe uma nova cópia do modelo antes de preenchê-lo, pois a lista de usuários e os cadastros disponíveis podem ter mudado desde o último download.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('36068784-ff6a-4ebc-9e2b-3d285f4c53e6','pt_MZ','ATTENDEE_README_STEP_2','As colunas destacadas em cinza (ID do usuário, Nome, ID de login, Função, Limite e ID do registro) estão bloqueadas e não devem ser editadas. Quaisquer alterações nessas colunas farão com que essa linha seja rejeitada no upload.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d187ed66-d8ad-4648-9ed1-05aed3d2da71','pt_MZ','ATTENDEE_README_STEP_3','Este modelo é específico para um único registro — o ID do registro já está pré-preenchido para todas as linhas e não pode ser alterado. Se você precisar mapear usuários para um cadastro diferente, baixe o modelo desse cadastro separadamente.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4e59d1e-899d-4641-8d51-db0d53c7d034','pt_MZ','ATTENDEE_README_STEP_4','`Data de inscrição` é obrigatória para todos os usuários. Decide a partir de quando a presença pode ser marcada no cadastro. As linhas sem esta data serão ignoradas e os usuários não serão mapeados. Insira a data no formato DD-MM-AAAA. A data deve estar dentro da duração da campanha','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('643be69e-595e-4b46-a45d-0ef59019555f','pt_MZ','ATTENDEE_README_STEP_5','Data de cancelamento de inscrição: A coluna Data de cancelamento de inscrição é opcional. Se você inserir aqui uma data futura, o usuário permanecerá ativo até aquela data e a marcação de presença será automaticamente bloqueada a partir do dia seguinte.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('de542489-6f38-4e1f-8fee-a8c9984ddafb','pt_MZ','ATTENDEE_README_STEP_6','Se você precisar mover um usuário de um registro para outro, primeiro ele deverá ser desinscrito do registro atual. Após o cancelamento da inscrição, eles poderão ser mapeados para um novo cadastro em qualquer dia após a data do cancelamento da inscrição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('dbb67227-d2cc-4e93-9d92-f25d508ebf69','pt_MZ','ATTENDEE_README_STEP_7','O que acontece depois do upload: seu arquivo será processado em segundo plano. Você verá uma atualização de status nesta tela assim que o processamento for concluído.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
