INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('20cdc0e1-6cf8-4697-bfc5-60bd06b71210','pt_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_ATTENDANCEFLOW','Registar a presença dos trabalhadores de campo e dos beneficiários durante as actividades de distribuição. Garante um rastreamento preciso da participação para relatórios.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7e6edf28-ad62-4987-8575-f1e502bb141c','pt_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_COMPLAINTFLOW','Registre e gerencie reclamações de campanhas de distribuição. Permite captura e resolução rápida de problemas para melhorar a qualidade do serviço.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5bc39114-88bc-45f9-bce1-0f6978617030','pt_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_DELIVERYFLOW','Monitorar os níveis de estoque líquido de inseticidas e a logística de distribuição. Rastreie o estoque em locais e pontos de distribuição.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c9ccbf6d-6290-4403-911b-096641dd8e07','pt_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_HFREFERALFLOW','Referência é o processo de direcionar uma pessoa, cliente ou caso a outro indivíduo, profissional ou organização para obter mais assistência, serviços ou experiência.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5b0e2892-3cfc-422b-9332-f34e088fe72e','pt_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_INVENTORYFLOW','Este módulo facilita a gestão eficiente do estoque de campanhas de saúde. Permite que os trabalhadores da linha da frente entreguem medicamentos essenciais.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('fb5b29e3-f93d-4dc3-a75d-3ede03d64dda','pt_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_REGISTRATIONFLOW','Este módulo facilita o cadastramento eficiente de beneficiários em campanhas de saúde. Ele permite que os funcionários da linha de frente capturem detalhes essenciais, como informações pessoais, dados demográficos e histórico de saúde.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
