INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b1879e36-9dcb-41be-9543-58077f5d8987','pt_MZ','MICROPLAN_PAYS','Pays','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('04085eb8-beaa-401b-be1a-1ff00dd62eff','pt_MZ','MODULE_DESCRIPTION_INSIDEMONITORING','Captura dados pós-campanha a nível familiar para validar a cobertura vacinal, semelhante ao LQAS. Os monitores registram pontos de GPS, respostas de pesquisas, motivos de vacinação perdida, conscientização do cuidador e detalhes de vigilância. Fornece um resumo da liquidação (contagem de crianças perdidas, sinalizadores de risco, status de cobertura, comentários) e é acessível apenas para funções de monitor configuradas.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('811666d0-65be-44f2-8bdc-244f8fc2c378','pt_MZ','MODULE_DESCRIPTION_LQA','O cabeçalho do lote/grupo em uma pesquisa LQA registra detalhes de localização, informações do topógrafo e coordenadas GPS. Inclui estado, distrito, vila, ID do cluster, nome do enumerador, detalhes do supervisor, latitude, longitude e data da pesquisa. Isso garante rastreamento, verificação e relatórios precisos das atividades de pesquisa de campo.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('4e7ef214-d251-4593-ad34-69834a7b17e1','pt_MZ','MODULE_DESCRIPTION_STOCK','Acompanhe e atualize os níveis de estoque de recursos em cada ponto de distribuição. Registre receitas, saídas, consumo e perdas para manter uma visibilidade precisa dos medicamentos durante a campanha.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2488f127-06f2-419a-8cf5-7c3ae45168cd','pt_MZ','MODULE_FEATURES','Recursos do módulo','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9c81637c-39a4-45c7-9450-843328851867','pt_MZ','MODULE_FEATURES_DESCRIPTION','Ative ou desative recursos específicos do aplicativo para sua campanha. Alguns recursos precisam de configuração para corresponder ao seu fluxo de trabalho. Outros trabalham com configurações padrão.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7b30c260-c263-4e04-b687-2aaaf156e334','pt_MZ','MONITORING_ITN_DP','Monitoramento','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
