INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('91a904eb-8f8f-4fec-8228-e566702722bc','pt_MZ','NUMBER_OF_DAILY_PHOTOS','Número de fotos diárias','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d0c8d837-3460-47ce-93dd-cc2aceba1d26','pt_MZ','NUMBER_OF_DAILY_PHOTOS_DESC','Isso define o número de vezes que os trabalhadores são solicitados a tirar fotos. Manter esse valor muito alto pode interferir na entrega da campanha e aumentar os custos de dados.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
