INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('03000d01-ffd1-448a-a4df-ad569354eeea','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_1','L''ID de registre est requis lorsque la limite est sélectionnée : une colonne de limite a été remplie mais la cellule ID de registre est vide. L''ID de registre est automatiquement renseigné par une formule : assurez-vous de ne pas l''avoir effacé accidentellement.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('b33c58ab-c1d4-4dd5-af16-9f08c15cdddf','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_2','Au moins une limite doit être sélectionnée pour le registre — Un ID de registre a été saisi mais aucune colonne de limite n''a de valeur. Remplissez au moins une colonne de limite pour chaque ligne de registre.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0d8560f6-f104-41a9-93d1-f76d2e96becf','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_3','Error 500 (Server Error)!!1500.That’s an error.There was an error. Please try again later.That’s all we know.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bc1f48d4-1ff0-4ba2-a72c-f934e1141e0d','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_4','ID de registre en double trouvé : le même ID de registre apparaît plus d''une fois dans la feuille. Chaque registre doit avoir un identifiant unique. Si vous avez créé plusieurs registres à la même limite, écrasez l''ID de registre renseigné automatiquement pour rendre chacun d''entre eux unique.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('553a99c8-9241-4fb0-8c54-75aba3934056','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_5','L''ID de registre existe déjà dans le système — Cet ID de registre a déjà été créé lors d''un téléchargement précédent. Supprimez ou renommez la ligne en double avant de la télécharger à nouveau.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('773d4a26-6e4a-43f3-8288-31849ee0fc2a','fr_MZ','ATTENDANCE_REGISTER_README_ERROR_HEADER','Erreurs courantes et leur signification :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('273a43d1-6cbc-44cc-9cd4-c8e52486dc35','fr_MZ','ATTENDANCE_REGISTER_README_HEADER_1','Comment remplir ce modèle :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cb77f610-675a-4fde-8fd2-a733704b3a1e','fr_MZ','ATTENDANCE_REGISTER_README_IMPORTANT','Important','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('86da3e80-0115-4e22-abce-998e806c7ae1','fr_MZ','ATTENDANCE_REGISTER_README_IMPORTANT_DESC','Une fois les registres créés avec succès, leurs limites et les détails du projet ne peuvent pas être modifiés à partir de cet écran. Contactez votre administrateur système pour toute correction.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2cf3a413-f0ad-45ce-8b7d-5a31b062c9b0','fr_MZ','ATTENDANCE_REGISTER_README_STEP_1','Téléchargez le modèle à l''aide du bouton ci-dessus et ouvrez-le dans Microsoft Excel ou dans un tableur compatible. Ne convertissez pas le fichier au format CSV avant de le télécharger, car les formules de remplissage automatique dans la colonne ID de registre pourraient cesser de fonctionner.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('e0710958-38d9-4251-a15f-634d9d3e5c7f','fr_MZ','ATTENDANCE_REGISTER_README_STEP_2','Chaque ligne du modèle représente un registre de présence. Remplissez les colonnes de limites de gauche à droite – par exemple, État, puis District, puis le niveau le plus bas auquel vous souhaitez que le registre soit créé. Vous devez remplir au moins une colonne de limite par ligne ; les lignes sans limite remplie seront rejetées. Le registre sera créé au niveau de limite le plus bas que vous avez rempli.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c40f9892-ac24-4cbd-8063-9573194ad06e','fr_MZ','ATTENDANCE_REGISTER_README_STEP_3','La colonne ID de registre est automatiquement renseignée en fonction de la limite la plus basse que vous entrez. Vous pouvez écraser cette valeur si vous souhaitez un nom personnalisé, mais chaque identifiant de registre dans la feuille doit être unique : les identifiants en double provoqueront une erreur et l''intégralité du téléchargement sera rejetée jusqu''à ce qu''elle soit résolue.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4eb4071-1132-45c6-b7ce-83cff7c22b8c','fr_MZ','ATTENDANCE_REGISTER_README_STEP_4','Que se passe-t-il après le téléchargement : Votre fichier sera traité en arrière-plan. Vous verrez une mise à jour du statut sur cet écran une fois le traitement terminé. Si des lignes contiennent des erreurs, vous pourrez télécharger une copie de votre fichier avec les détails des erreurs notés pour chaque ligne. Corrigez les lignes marquées et téléchargez à nouveau pour terminer la création du registre.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('33b79ff2-55dd-4484-8be2-2146e583e7c0','fr_MZ','ATTENDEE_README_ENROLLMENT_DESC_1','Lorsqu''un utilisateur est mappé à un registre, sa date d''inscription est automatiquement définie sur la date de mappage — vous n''avez pas besoin de remplir cette colonne. La date d''inscription détermine à partir de quel jour la présence peut être marquée pour cet utilisateur.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8e3bf306-6977-4ca6-98ef-f985b8aa4aba','fr_MZ','ATTENDEE_README_ENROLLMENT_DESC_2','Si vous devez supprimer un utilisateur d''un registre, définissez sa colonne Statut sur Désactivé. Cela déclenchera une désinscription immédiate et la présence ne pourra plus être marquée pour cet utilisateur à partir de cette date. Si vous saisissez plutôt une date future dans la colonne Date de désinscription, l''utilisateur restera actif jusqu''à cette date et la notation de présence sera automatiquement bloquée après celle-ci.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('71da6929-11a5-4b39-91f4-9223c207128b','fr_MZ','ATTENDEE_README_ENROLLMENT_DESC_3','Si vous devez déplacer un utilisateur d''un registre à un autre, vous devez d''abord le désactiver de son registre actuel. Une fois que leur statut est défini sur Désactivé et que le fichier est téléchargé, ils peuvent être mappés à un nouveau registre, cela peut être fait le même jour.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('21d17aee-4872-4ffe-babe-f45b1ddfe64f','fr_MZ','ATTENDEE_README_ERROR_1','L''ID de registre est requis : un ID de registre pré-rempli a été accidentellement effacé. Téléchargez à nouveau le modèle et ne modifiez aucune cellule pré-remplie.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9669a02e-c43a-4d15-a0e0-7821c8757003','fr_MZ','ATTENDEE_README_ERROR_10','Impossible de modifier la date de désinscription pour ce registre — La date de désinscription est verrouillée une fois définie. Contactez votre administrateur système si cela doit être modifié.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6bf144dc-9e9e-425a-a6c8-32127bb48d66','fr_MZ','ATTENDEE_README_ERROR_2','L''ID de registre ne correspond pas au registre attendu : une ligne contient un ID de registre provenant d''un modèle différent. Téléchargez à nouveau le modèle de ce registre et saisissez à nouveau les données.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3940e4c1-816b-45dd-8a56-3d13f9a8c58e','fr_MZ','ATTENDEE_README_ERROR_3','Le registre existe déjà dans une autre campagne — Le registre appartient à une autre campagne et la fiche entière sera rejetée. Assurez-vous d''avoir téléchargé le modèle de la bonne campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('aae744f1-b0bc-4133-a5ff-d8e1acc07dcc','fr_MZ','ATTENDEE_README_ERROR_4','La date d''inscription est requise pour inscrire un nouveau participant ou un nouveau membre du personnel. La date d''inscription est obligatoire pour tous les nouveaux utilisateurs et doit également être renseignée si le code d''équipe ou la date de désinscription est saisi. Utilisez le format JJ-MM-AAAA ou JJ/MM/AAAA.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('78ffe7d9-9b79-495d-a72a-e72243f0de47','fr_MZ','ATTENDEE_README_ERROR_5','Format de date invalide. Use DD-MM-YYYY or DD/MM/YYYY — A date cell contains an unrecognised format or extra characters. Accepted formats are DD-MM-YYYY and DD/MM/YYYY only.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('bbb22b27-bd40-4b56-821c-ea697201fbaf','fr_MZ','ATTENDEE_README_ERROR_6','La date doit être comprise entre les dates de début et de fin du registre — Une date d''inscription ou de désinscription se situe en dehors de la plage de dates valide du registre. Vérifiez les dates de la campagne et corrigez en conséquence.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d8e4039a-c4cc-4431-83e2-5a5ae4096bf1','fr_MZ','ATTENDEE_README_ERROR_7','La date de désinscription ne peut pas être antérieure à la date d''inscription : la date de désinscription est antérieure à la date d''inscription sur la même ligne. Corriger pour que la désinscription ait lieu au moment de l''inscription ou après.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('2392ebd2-7633-43dd-8f9d-5cf6243a5824','fr_MZ','ATTENDEE_README_ERROR_8','L''individu est déjà activement inscrit dans un autre registre de présence — Cet utilisateur doit être désinscrit de son registre actuel avant d''être ajouté ici. Une fois désinscrits, ils peuvent être mappés à ce registre le même jour.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('0e23460e-b038-4e3f-a096-ab1122b712b3','fr_MZ','ATTENDEE_README_ERROR_9','Impossible de modifier la date d''inscription pour ce registre — La date d''inscription de l''inscription précédente d''un utilisateur dans ce registre ne peut pas être modifiée. Laissez-le tel qu''il était dans le dossier original.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9f55be14-e55a-460c-b080-972e10c5afa2','fr_MZ','ATTENDEE_README_HEADER_1','Comment remplir ce modèle :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('8f095f75-8e53-40d9-b97e-51585ab040c7','fr_MZ','ATTENDEE_README_HEADER_2','Erreurs courantes et leur signification :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a4427dba-3617-4bd9-aadb-de9e652cadc7','fr_MZ','ATTENDEE_README_HEADER_3','Erreurs courantes et leur signification :','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a574bbe7-f67f-43fa-986f-b987bb68e90e','fr_MZ','ATTENDEE_README_STEP_1','Téléchargez le modèle en utilisant le bouton ci-dessus. Le modèle sera pré-rempli avec tous les utilisateurs actuellement créés dans le système, répartis sur trois feuilles : travailleurs de première ligne, marqueurs de présence et approbateurs de présence. Téléchargez toujours une nouvelle copie du modèle avant de le remplir, car la liste des utilisateurs et les registres disponibles peuvent avoir changé depuis votre dernier téléchargement.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6cd0e442-db2c-4251-97da-4c754a5cd1f7','fr_MZ','ATTENDEE_README_STEP_2','Les colonnes surlignées en gris (ID utilisateur, nom, ID de connexion, rôle, limite et ID de registre) sont verrouillées et ne doivent pas être modifiées. Toute modification apportée à ces colonnes entraînera le rejet de cette ligne lors du téléchargement.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5bcb5fd6-5538-49db-a544-b43f8386de89','fr_MZ','ATTENDEE_README_STEP_3','Ce modèle est spécifique à un seul registre : l''ID du registre est déjà pré-rempli pour toutes les lignes et ne peut pas être modifié. Si vous devez mapper les utilisateurs à un autre registre, téléchargez le modèle de ce registre séparément.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('9c43c7e4-d7ad-4cbe-99d5-a0907268cfd3','fr_MZ','ATTENDEE_README_STEP_4','La « Date d''inscription » est obligatoire pour tous les utilisateurs. Il décide à partir de quand la présence peut être inscrite sur le registre. Les lignes sans cette date seront ignorées et les utilisateurs ne seront pas mappés. Saisissez la date au format JJ-MM-AAAA. La date doit être comprise dans la durée de la campagne','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('c8daaec7-cbdb-436a-9f5e-d1e2581bc167','fr_MZ','ATTENDEE_README_STEP_5','Date de désinscription : La colonne Date de désinscription est facultative. Si vous saisissez ici une date future, l''utilisateur restera actif jusqu''à cette date et le marquage de présence sera automatiquement bloqué à partir du lendemain.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('3401687f-9b23-4719-9244-aeb6efeb434b','fr_MZ','ATTENDEE_README_STEP_6','Si vous devez déplacer un utilisateur d''un registre à un autre, il doit d''abord être désinscrit de son registre actuel. Une fois désinscrits, ils peuvent être mappés à un nouveau registre n’importe quel jour après leur date de désinscription.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('cd542771-b555-4354-a086-06c4fe0a70f1','fr_MZ','ATTENDEE_README_STEP_7','Que se passe-t-il après le téléchargement : Votre fichier sera traité en arrière-plan. Vous verrez une mise à jour du statut sur cet écran une fois le traitement terminé.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
