INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('6f4984dc-2cef-44a1-b1b0-5fc19d5ff661','fr_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_ATTENDANCEFLOW','Présence record des agents de terrain et des bénéficiaires lors des activités de distribution. Assure un suivi précis de la participation pour les rapports.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a1b54ff5-5675-4d02-916c-2e6f659864b0','fr_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_COMPLAINTFLOW','Enregistrez et gérez les plaintes liées aux campagnes de distribution. Permet une capture et une résolution rapides des problèmes pour améliorer la qualité du service.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('5da08399-301a-4807-b343-45ff0ae77b72','fr_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_DELIVERYFLOW','Surveiller les niveaux de stocks nets d’insecticides et la logistique de distribution. Suivez l’inventaire sur tous les sites et points de distribution.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7a5ef5b6-8e15-463d-8595-6d8b43a4190e','fr_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_HFREFERALFLOW','La référence est le processus consistant à diriger une personne, un client ou un cas vers une autre personne, un professionnel ou une organisation pour obtenir une assistance, des services ou une expertise supplémentaires.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7da739d3-cd00-4f11-869e-16428a4e6ad8','fr_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_INVENTORYFLOW','Ce module facilite une gestion efficace des stocks des campagnes de santé. Il permet aux travailleurs de première ligne de livrer des médicaments essentiels.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('66f0649b-9448-4de2-8e93-1c1249ef124e','fr_MZ','HCM_MODULE_DESCRIPTION_LLIN-MZ_REGISTRATIONFLOW','Ce module facilite l''enregistrement efficace des bénéficiaires dans les campagnes de santé. Il permet aux travailleurs de première ligne de capturer des détails essentiels tels que des informations personnelles, des données démographiques et des antécédents médicaux.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
