INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('ddf61eb8-3bc4-4857-909f-b247f729127a','fr_MZ','MODULE_DESCRIPTION_INSIDEMONITORING','Capture les données post-campagne au niveau des ménages pour valider la couverture vaccinale, similaire au LQAS. Les moniteurs enregistrent les points GPS, les réponses aux enquêtes, les raisons de vaccination manquées, la sensibilisation des soignants et les détails de la surveillance. Fournit un résumé du règlement (nombre d’enfants manqués, indicateurs de risque, statut de couverture, commentaires) et est accessible uniquement aux rôles de surveillance configurés.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('7d5b8cbe-5eec-4500-a69d-fcb8b82a7201','fr_MZ','MODULE_DESCRIPTION_LQA','L''en-tête de lot/cluster d''une enquête LQA enregistre les détails de l''emplacement, les informations de l''arpenteur et les coordonnées GPS. Il comprend l''état, le district, le village, l''identifiant du cluster, le nom de l''enquêteur, les détails du superviseur, la latitude, la longitude et la date de l''enquête. Cela garantit un suivi, une vérification et un reporting précis des activités d’enquête sur le terrain.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('157373bf-a8fe-4b1d-88c1-8674b72d966e','fr_MZ','MODULE_DESCRIPTION_STOCK','Suivez et mettez à jour les niveaux de stock de ressources à chaque point de distribution. Enregistrez les réceptions, les problèmes, la consommation et les pertes pour maintenir une visibilité précise des médicaments tout au long de la campagne.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d19fda66-d1a7-43fa-9bbd-6066d8f64fb7','fr_MZ','MODULE_FEATURES','Caractéristiques des modules','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('a0060863-e4d3-4e99-948f-ffc76f24b0e5','fr_MZ','MODULE_FEATURES_DESCRIPTION','Activez ou désactivez des fonctionnalités d''application spécifiques pour votre campagne. Certaines fonctionnalités nécessitent une configuration pour correspondre à votre flux de travail. D''autres fonctionnent avec les paramètres par défaut.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
