INSERT INTO message (id,locale,code,message,tenantid,module,createdby,createddate,lastmodifiedby,lastmodifieddate) VALUES ('d01f9050-d5ea-47c6-84ed-f625665b6c99','fr_MZ','NUMBER_OF_DAILY_PHOTOS_DESC','Cela définit le nombre de fois où les travailleurs sont invités à prendre des photos. Maintenir ce chiffre trop élevé peut interférer avec la diffusion de la campagne et augmenter les coûts des données.','mz','hcm-campaignmanager',1,now(),1,now()) ON CONFLICT (tenantid,locale,module,code) DO NOTHING;
